<?php require_once __DIR__.'/../includes/functions.php';require_once __DIR__.'/../includes/database.php';$error='';if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();try{$q=db()->prepare('SELECT id,password_hash FROM admins WHERE username=?');$q->execute([trim($_POST['username']??'')]);$a=$q->fetch();if($a&&password_verify((string)($_POST['password']??''),$a['password_hash'])){session_regenerate_id(true);$_SESSION['admin_id']=$a['id'];header('Location: /admin/');exit;}}catch(Throwable $e){}$error='Unable to sign in.';}?><!doctype html><html><meta charset="utf-8"><title>Admin login</title><link rel="stylesheet" href="/assets/css/site.css"><body><main class="content"><h1>Admin login</h1><?php if($error)echo '<p class="notice">'.e($error).'</p>';?><form method="post"><input type="hidden" name="_csrf" value="<?=e(csrf())?>"><div class="form-field"><label>Username</label><input name="username" required></div><div class="form-field"><label>Password</label><input type="password" name="password" required></div><button class="button button-dark">Sign in</button></form></main></body></html>
